import React from 'react';
import { useOutletContext } from 'react-router-dom';
import ProjectNavbar from '../../components/ProjectNavbar';

const Work_P4 = () => {
  const context = useOutletContext();
  const resumeData = contextHub?.work?.data;

  return (
    <div className="workspace-container">
      <ProjectNavbar basePath="work" links={["Streaming", "Collab", "Nodes", "Logs"]} />
      <div className="summary-box">
        <h3>Unified Telemetry Engine Harvest Logs</h3>
        <pre style={{ backgroundColor: '#1e293b', color: '#38bdf8', padding: '1rem', marginTop: '1rem', borderRadius: '6px' }}>
          {resumeData ? JSON.stringify({ event: "WORKSPACE_SYNC_METRIC", performance: `${resumeData.latency || 0}ms`, payload_integrity: `${resumeData.score}%` }, null, 2) : "> System idling. Awaiting initialization telemetry capture event..."}
        </pre>
      </div>
    </div>
  );
};
export default Work_P4;
